/**
 * 一次性补齐历史生成物的标记（`// Auto-generated by Codegen Engine`）。
 *
 * 为什么需要单独一次: 安全写入器**拒绝覆盖无标记的文件**（那是手写保护，见
 * `scripts/lib/generated-file.cjs`）。而这批历史文件确实是生成物、只是早于"标记"这个约定。
 * 所以用一条**保守规则**区分它们与真手写:
 *
 *   去掉标记行后，文件内容与当前生成器的输出**完全一致**  => 是生成物，补标记
 *   否则（有人改过）                                        => 保留不动，它继续留在手写基线里
 *
 * 用法: pnpm exec tsx scripts/backfill-generated-marker.ts [--write]
 */
import fs from "node:fs"
import path from "node:path"
import {
  generateFormComponent, generateListPage, generateRepository, generateService,
  generateTypes, generateValidator,
} from "../packages/domains/infra/backend/services/codegen-templates"

const ROOT = path.resolve(__dirname, "..")
const write = process.argv.includes("--write")
const MARKER = "// Auto-generated by Codegen Engine"

let added = 0, kept = 0, missing = 0
for (const domain of process.argv.slice(2).filter((a) => !a.startsWith("--"))) {
  const mod = require(path.join(ROOT, "scripts", "data", `${domain}-source-tables.ts`)) as Record<string, unknown>
  const configs = mod[`${domain.toUpperCase()}_TABLES`] as Array<never>
  if (!Array.isArray(configs)) continue
  for (const cfg of configs) {
    for (const out of [generateFormComponent(cfg), generateListPage(cfg), generateRepository(cfg), generateService(cfg), generateTypes(cfg), generateValidator(cfg)]) {
      const full = path.resolve(ROOT, out.path)
      if (!fs.existsSync(full)) { missing++; continue }
      const existing = fs.readFileSync(full, "utf8")
      if (existing.includes(MARKER)) { kept++; continue }
      // 保守判据: 去掉首行后与生成器输出一致 => 确系生成物
      const withoutFirstLine = existing.slice(existing.indexOf("\n") + 1)
      if (out.content.slice(out.content.indexOf("\n") + 1) === withoutFirstLine) {
        if (write) fs.writeFileSync(full, out.content)
        added++
      } else {
        kept++
      }
    }
  }
}
console.log(`  ${write ? "已补标记" : "可补标记"} ${added} 个 / 内容已被改动而保留 ${kept} 个 / 文件不存在 ${missing} 个`)
